"""Offline synthetic learning platform scenarios; no live transactions."""
import base64,copy,random
from pathlib import Path
from functools import lru_cache
PAGE_STATES={'home': ['recommended', 'trending', 'business', 'cookie_dialog', 'notifications_drawer', 'account_popover'], 'categories': ['development', 'design', 'business', 'filters_drawer', 'preview_dialog', 'cookie_dialog'], 'search': ['relevance', 'highest_rated', 'newest', 'filters_drawer', 'preview_dialog', 'search_popover'], 'course_detail': ['overview', 'curriculum', 'reviews', 'preview_dialog', 'gift_dialog', 'share_dialog'], 'my_learning': ['all_courses', 'in_progress', 'completed', 'collection_dialog', 'reminder_dialog', 'account_popover'], 'player': ['playing', 'paused', 'transcript', 'speed_popover', 'captions_popover', 'review_dialog'], 'notes': ['all_notes', 'bookmarked', 'search_notes', 'note_dialog', 'delete_dialog', 'export_dialog'], 'questions': ['popular', 'recent', 'unanswered', 'question_dialog', 'report_dialog', 'reply_dialog'], 'wishlist': ['all', 'price_drop', 'recently_added', 'collection_dialog', 'remove_dialog', 'preview_dialog'], 'cart': ['items', 'coupon_applied', 'saved_for_later', 'coupon_dialog', 'remove_dialog', 'gift_dialog'], 'checkout': ['card', 'wallet', 'order_summary', 'billing_dialog', 'payment_error_dialog', 'success_dialog'], 'instructor': ['profile', 'courses', 'reviews', 'follow_dialog', 'message_dialog', 'share_dialog'], 'dashboard': ['overview', 'engagement', 'revenue', 'date_dialog', 'export_dialog', 'announcement_dialog'], 'course_manager': ['curriculum', 'pricing', 'landing_page', 'lesson_dialog', 'upload_dialog', 'publish_dialog'], 'messages': ['inbox', 'unread', 'sent', 'message_dialog', 'attachment_dialog', 'report_dialog'], 'notifications': ['all', 'learning', 'promotions', 'notification_settings_dialog', 'delete_dialog', 'account_popover'], 'purchase_history': ['courses', 'refunds', 'receipts', 'receipt_dialog', 'refund_dialog', 'billing_dialog'], 'plans': ['personal', 'teams', 'annual', 'plan_dialog', 'cancel_dialog', 'cookie_dialog'], 'settings': ['profile', 'privacy', 'notifications', 'password_dialog', 'email_dialog', 'delete_dialog'], 'help': ['browse', 'article', 'contact', 'contact_dialog', 'feedback_dialog', 'cookie_dialog']}
TITLES=['Python: From First Script to Real Projects','The Complete Web Development Workshop','Practical Data Analysis with SQL','User Experience Design Fundamentals','Machine Learning Through Hands-on Projects','Excel for Everyday Business Decisions','Photography: Light, Composition and Story','Project Management Essentials','Build Accessible React Interfaces','Digital Marketing Strategy in Practice','Cloud Architecture Foundations','Speak Confidently: Presentation Skills','Modern JavaScript Patterns','A Practical Guide to Product Management','Illustration and Visual Thinking','Cybersecurity Fundamentals','Financial Modeling for Beginners','Build Better Habits for Learning','Advanced Python Automation','Design Systems from Scratch','Introduction to Generative AI','Business Writing that Works','Mobile App Design Studio','Statistics for Curious Minds']
NAMES=['Maya Rivers','Alex Chen','Nora Fields','Theo Brooks','Lina Park','Amir Costa','Emma Lane','Ravi Morgan']
@lru_cache(maxsize=1)
def font_uri():return 'data:font/woff2;base64,'+base64.b64encode((Path(__file__).resolve().parents[1]/'assets/material-symbols-rounded.woff2').read_bytes()).decode()
@lru_cache(maxsize=64)
def artwork(i):
 colors=['#5022c3','#1e6055','#263d71','#9b3b54','#5a3c73','#825b16'];c=colors[i%6]
 svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 360"><rect width="640" height="360" fill="'+c+'"/><circle cx="540" cy="40" r="160" fill="#ffffff" opacity=".1"/><rect x="44" y="53" width="360" height="240" rx="15" fill="#171b25"/><path d="M75 95h95M75 135h220M75 175h145M75 215h195M75 255h90" stroke="#c8adff" stroke-width="12"/><circle cx="487" cy="231" r="73" fill="#e3d6ff"/><path d="m468 194 49 37-49 37Z" fill="'+c+'"/></svg>'
 return 'data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()
def generate_data(sample_index=0,page='home',media_dir=None):
 if page not in PAGE_STATES:raise ValueError(page)
 pool=sorted(p for p in (Path(media_dir)/'courses').glob('*') if p.suffix.lower() in {'.png','.jpg','.jpeg','.webp'}) if media_dir else []
 def image(i):
  if not pool:return artwork(i)
  p=pool[(i+sample_index)%len(pool)];return 'data:image/'+('jpeg' if p.suffix.lower() in {'.jpg','.jpeg'} else p.suffix[1:])+';base64,'+base64.b64encode(p.read_bytes()).decode()
 people=[dict(name=n,initials=''.join(x[0] for x in n.split())) for n in NAMES]
 courses=[dict(id=i,title=TITLES[(i+sample_index)%24],image=image(i),author=people[i%8],rating=round(4.5+i%5/10,1),reviews=1240+i*347,price='$'+str(14+i%5)+'.99',hours=12+i*2,lectures=76+i*9,progress=(i*17+23)%101) for i in range(24)]
 return dict(page=page,page_states=[x.replace('_',' ').title() for x in PAGE_STATES[page][:3]],state=PAGE_STATES[page][0],popup_visible=False,font_uri=font_uri(),profile=people[0],people=people,courses=courses,query='python development',tab_labels=['Udemy · '+page.replace('_',' ').title(),'Python course','My learning'])
def apply_state(data,state):
 if state not in PAGE_STATES[data['page']]:raise ValueError(state)
 d=copy.deepcopy(data);d['courses']=sorted(d['courses'],key=lambda c:c['rating'],reverse=True) if state=='highest_rated' else list(reversed(d['courses'])) if state in ['newest','recently_added','recent'] else [c for c in d['courses'] if c['progress']<70] if state=='in_progress' else [dict(c,progress=100) for c in d['courses'][:8]] if state=='completed' else [c for c in d['courses'] if c['id']%3=={'development':0,'design':1,'business':2}.get(state,c['id']%3)] if state in ['development','design','business'] else d['courses'];d['page_states']=[x.replace('_',' ').title() for x in PAGE_STATES[data['page']][:3]];d.update(state=state,popup_visible=state.endswith(('_dialog','_drawer','_popover')),dialog_title=state.replace('_dialog','').replace('_drawer','').replace('_popover','').replace('_',' ').title());return d
def reference_theme(mode='light'):
 dark=mode=='dark';text='#F0F1F3' if dark else '#24272B';surface='#272A30' if dark else '#FFFFFF'
 return dict(mode=mode,semantic={'background':'#191C21' if dark else '#FFFFFF','on_background':text,'surface':surface,'on_surface':text,'surface_variant':'#363B44' if dark else '#E7ECF0','on_surface_variant':text,'primary':'#86BEF5' if dark else '#6d28d9','on_primary':'#112844' if dark else '#FFFFFF','border':'#73808E' if dark else '#BCC6CE','icon':text,'error':'#FFB0AE' if dark else '#B32D31'})

